-- Generated by `python -m pipelines.metrics`; do not edit by hand.
-- Measurement window: 2026-10-02 to 2026-10-08 (Eastern calendar days, inclusive).

-- events_per_day
SELECT to_date(from_utc_timestamp(started_at, 'America/New_York')) AS run_date,
       count(DISTINCT run_id) AS runs,
       sum(coalesce(cast(get_json_object(metrics, '$.vehicle_positions_rows_added') AS BIGINT), 0))
         AS vehicle_positions,
       sum(coalesce(cast(get_json_object(metrics, '$.trip_updates_rows_added') AS BIGINT), 0))
         AS trip_updates,
       sum(coalesce(cast(get_json_object(metrics, '$.vehicle_positions_rows_added') AS BIGINT), 0)
         + coalesce(cast(get_json_object(metrics, '$.trip_updates_rows_added') AS BIGINT), 0)) AS events
FROM workspace.transit.ops_run_log
WHERE step = 'bronze' AND status = 'succeeded' AND to_date(from_utc_timestamp(started_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'
GROUP BY 1
ORDER BY 1;

-- freshness
SELECT count(*) AS builds,
       percentile(freshness_s, 0.5) AS median_s,
       percentile(freshness_s, 0.95) AS p95_s,
       round(avg(freshness_s), 1) AS mean_s,
       min(freshness_s) AS min_s,
       max(freshness_s) AS max_s
FROM (
  SELECT cast(get_json_object(metrics, '$.freshness_s') AS INT) AS freshness_s
  FROM workspace.transit.ops_run_log
  WHERE step = 'gold' AND status = 'succeeded' AND run_id <> 'manual' AND to_date(from_utc_timestamp(started_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'
)
WHERE freshness_s IS NOT NULL;

-- rows_removed
SELECT feed, bronze, silver, quarantined,
       bronze - silver - quarantined AS removed,
       round(100.0 * (bronze - silver - quarantined) / bronze, 2) AS pct_removed
FROM (
  SELECT 'vehicle_positions' AS feed,
         (SELECT count(*) FROM workspace.transit.bronze_vehicle_positions WHERE to_date(from_utc_timestamp(_ingested_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08') AS bronze,
         (SELECT count(*) FROM workspace.transit.silver_vehicle_positions WHERE to_date(from_utc_timestamp(_ingested_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08') AS silver,
         (SELECT count(*) FROM workspace.transit.silver_quarantine
          WHERE feed = 'vehicle_positions' AND to_date(from_utc_timestamp(_quarantined_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08') AS quarantined
  UNION ALL
  SELECT 'trip_updates',
         (SELECT count(*) FROM workspace.transit.bronze_trip_updates WHERE to_date(from_utc_timestamp(_ingested_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'),
         (SELECT count(*) FROM workspace.transit.silver_trip_updates WHERE to_date(from_utc_timestamp(_ingested_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'),
         (SELECT count(*) FROM workspace.transit.silver_quarantine
          WHERE feed = 'trip_updates' AND to_date(from_utc_timestamp(_quarantined_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08')
);

-- data_quality
SELECT count(DISTINCT run_id) AS runs,
       count(*) AS checks,
       count_if(passed) AS passed,
       round(100.0 * count_if(passed) / count(*), 2) AS pct_checks_passed,
       count(DISTINCT run_id) - count(DISTINCT CASE WHEN NOT passed THEN run_id END) AS runs_all_passed
FROM workspace.transit.dq_results
WHERE run_id IN (SELECT run_id FROM workspace.transit.ops_run_log WHERE to_date(from_utc_timestamp(started_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08');

-- step_runtime
SELECT step,
       count(*) AS attempts,
       count_if(status = 'failed') AS failed,
       percentile(unix_timestamp(finished_at) - unix_timestamp(started_at), 0.5) AS median_s,
       max(unix_timestamp(finished_at) - unix_timestamp(started_at)) AS max_s
FROM workspace.transit.ops_run_log
WHERE to_date(from_utc_timestamp(started_at, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'
GROUP BY step
ORDER BY step;

-- job_runs
SELECT count(*) AS runs,
       count_if(failed_steps = 0) AS succeeded,
       round(100.0 * count_if(failed_steps = 0) / count(*), 2) AS pct_succeeded,
       min(first_start) AS first_run,
       max(first_start) AS last_run
FROM (
  SELECT run_id, min(started_at) AS first_start,
         count_if(last_status = 'failed') AS failed_steps
  FROM (
    SELECT run_id, step, started_at,
           max_by(status, started_at) OVER (PARTITION BY run_id, step) AS last_status
    FROM workspace.transit.ops_run_log
    WHERE run_id <> 'manual'
  )
  GROUP BY run_id
)
WHERE to_date(from_utc_timestamp(first_start, 'America/New_York')) BETWEEN DATE'2026-10-02' AND DATE'2026-10-08';

-- run_coverage
SELECT run_date,
       count(*) AS runs,
       9 - count(*) AS missing_runs,
       count_if(failed_steps > 0) AS failed_runs,
       array_sort(collect_list(start_hour)) AS start_hours
FROM (
  SELECT run_id,
         to_date(from_utc_timestamp(min(started_at), 'America/New_York')) AS run_date,
         hour(from_utc_timestamp(min(started_at), 'America/New_York')) AS start_hour,
         count_if(last_status = 'failed') AS failed_steps
  FROM (
    SELECT run_id, step, started_at,
           max_by(status, started_at) OVER (PARTITION BY run_id, step) AS last_status
    FROM workspace.transit.ops_run_log
    WHERE run_id <> 'manual'
  )
  GROUP BY run_id
)
WHERE run_date BETWEEN DATE'2026-10-02' AND DATE'2026-10-08'
GROUP BY run_date
ORDER BY run_date;
